import { request, requestOrNull, seg, Page, requestFile, ExportRequest } from './apiSupport';
import { TicketDTO } from './TicketDTO';
import { TicketKeyDTO } from './TicketKeyDTO';
import { TicketSrchDTO } from './TicketSrchDTO';
import { TicketStatus } from './TicketStatus';

/**
 * REST client for Ticket.
 *
 * Calls the endpoints TicketController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/ticket';

/** Registers a new Ticket. */
export async function create(input: TicketDTO, init?: RequestInit): Promise<TicketDTO> {
    return request<TicketDTO>('POST', BASE, input, init);
}

/** The Ticket with this identifier, or null when there is none. */
export async function findById(ticketId: number, init?: RequestInit): Promise<TicketDTO | null> {
    return requestOrNull<TicketDTO>('GET', BASE + '/' + seg(ticketId), init);
}

/** Every Ticket matching the condition. */
export async function search(condition: TicketSrchDTO, init?: RequestInit): Promise<Page<TicketDTO>> {
    return request<Page<TicketDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Ticket. */
export async function update(input: TicketDTO, init?: RequestInit): Promise<TicketDTO> {
    return request<TicketDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: TicketDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: TicketKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Ticket with this identifier. */
export async function deleteById(ticketId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(ticketId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportTicket(body: ExportRequest<TicketSrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

/** Whether answer may be given now: the status is OPEN. */
export function canAnswer(value: TicketDTO | null | undefined): boolean {
    return value != null && (value.status === TicketStatus.OPEN);
}

/** Whether reopen may be given now: the status is ANSWERED or CLOSED. */
export function canReopen(value: TicketDTO | null | undefined): boolean {
    return value != null && (value.status === TicketStatus.ANSWERED || value.status === TicketStatus.CLOSED);
}

/** Whether close may be given now: the status is OPEN or ANSWERED. */
export function canClose(value: TicketDTO | null | undefined): boolean {
    return value != null && (value.status === TicketStatus.OPEN || value.status === TicketStatus.ANSWERED);
}

/** Whether it may be deleted now: the status is CLOSED. */
export function canDelete(value: TicketDTO | null | undefined): boolean {
    return value != null && (value.status === TicketStatus.CLOSED);
}

/** The answer command: Ticket decides, and answers with what it became. */
export async function answer(ticketId: number, init?: RequestInit): Promise<TicketDTO> {
    return request<TicketDTO>('POST', BASE + '/' + seg(ticketId) + '/answer', undefined, init);
}

/** The reopen command: Ticket decides, and answers with what it became. */
export async function reopen(ticketId: number, init?: RequestInit): Promise<TicketDTO> {
    return request<TicketDTO>('POST', BASE + '/' + seg(ticketId) + '/reopen', undefined, init);
}

/** The close command: Ticket decides, and answers with what it became. */
export async function close(ticketId: number, init?: RequestInit): Promise<TicketDTO> {
    return request<TicketDTO>('POST', BASE + '/' + seg(ticketId) + '/close', undefined, init);
}

